147		currentUser, err := s.fetchCurrentUser(ctx)
148		if err != nil {
149			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
150		}
151		if currentUser == nil {
152			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
153		}
154		if currentUser.Role != store.RoleAdmin {
155			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
156		}
157	
158		uid, err := ExtractIdentityProviderUIDFromName(request.Name)
159		if err != nil {
160			return nil, status.Errorf(codes.InvalidArgument, "invalid identity provider name: %v", err)
161		}
162		if s.Store.IsIdentityProviderDeploymentConfigured(uid) {
163			return nil, status.Errorf(codes.FailedPrecondition, "identity provider %q is configured by the deployment", uid)
164		}
165	
166		// Look up the IdP by UID to get the internal ID for deletion.
167		identityProvider, err := s.Store.GetStoredIdentityProvider(ctx, &store.FindIdentityProvider{UID: &uid})
168		if err != nil {
169			return nil, status.Errorf(codes.Internal, "failed to check identity provider existence: %v", err)
170		}
