22	const (
23		// DefaultDeploymentConfigurationDir is the directory scanned for runtime configuration files.
24		DefaultDeploymentConfigurationDir = "/etc/secrets"
25		maxDeploymentConfigurationSize    = 1 << 20
26		maxTranscriptionModelLength       = 256
27		maxTranscriptionLanguageLength    = 32
28		maxTranscriptionPromptLength      = 4096
29	)
30	
31	var (
32		idpDeploymentFilenameMatcher             = regexp.MustCompile(`^memos-idp-[a-z0-9]+(?:-[a-z0-9]+)*\.json$`)
33		instanceSettingDeploymentFilenameMatcher = regexp.MustCompile(`^memos-instance-setting-[a-z0-9]+(?:-[a-z0-9]+)*\.json$`)
34		protoJSONUnknownFieldMatcher             = regexp.MustCompile(`unknown field "([^"]+)"`)
35	)
36	
37	// LoadDeploymentConfiguration loads the default runtime deployment configuration.
38	func (s *Store) LoadDeploymentConfiguration(ctx context.Context) error {
39		return s.LoadDeploymentConfigurationDir(ctx, DefaultDeploymentConfigurationDir)
40	}
41	
42	// LoadDeploymentConfigurationDir loads and atomically publishes runtime configuration from dir.
43	func (s *Store) LoadDeploymentConfigurationDir(ctx context.Context, dir string) error {
44		entries, err := os.ReadDir(dir)
45		if err != nil {
46			if os.IsNotExist(err) {
47				s.setDeploymentConfiguration(newDeploymentConfiguration())
48				return nil
49			}
50			return errors.Wrap(err, "failed to read deployment configuration directory")
51		}
52	
53		config := newDeploymentConfiguration()
54		idpFiles := map[string]string{}
55		settingFiles := map[storepb.InstanceSettingKey]string{}
56		for _, entry := range entries {
57			name := entry.Name()
58			path := filepath.Join(dir, name)
59			switch {
60			case isIdentityProviderDeploymentFilename(name):
61				if !idpDeploymentFilenameMatcher.MatchString(name) {
62					slog.Warn("loading identity provider deployment file with a legacy filename; rename it to lowercase kebab case", "filename", name)
63				}
64				provider := &storepb.IdentityProvider{}
65				if err := readDeploymentProtoJSON(path, provider); err != nil {
66					return errors.Wrapf(err, "invalid identity provider deployment file %q", name)
67				}
68				if err := validateDeploymentIdentityProvider(provider); err != nil {
69					return errors.Wrapf(err, "invalid identity provider deployment file %q", name)
70				}
71				if previous, ok := idpFiles[provider.Uid]; ok {
72					return errors.Errorf("identity provider UID %q is declared by both %q and %q", provider.Uid, previous, name)
73				}
74				idpFiles[provider.Uid] = name
75				config.identityProviders[provider.Uid] = cloneIdentityProvider(provider)
76			case instanceSettingDeploymentFilenameMatcher.MatchString(name):
77				setting := &storepb.InstanceSetting{}
78				if err := readDeploymentProtoJSON(path, setting); err != nil {
79					return errors.Wrapf(err, "invalid instance setting deployment file %q", name)
80				}
81				if err := validateAndNormalizeDeploymentInstanceSetting(setting); err != nil {
82					return errors.Wrapf(err, "invalid instance setting deployment file %q", name)
83				}
84				if previous, ok := settingFiles[setting.Key]; ok {
85					return errors.Errorf("instance setting key %q is declared by both %q and %q", setting.Key, previous, name)
86				}
87				settingFiles[setting.Key] = name
88				config.instanceSettings[setting.Key] = cloneInstanceSetting(setting)
89			case strings.HasPrefix(name, "memos-"):
90				slog.Warn("ignoring unrecognized Memos deployment configuration filename", "filename", name)
91			default:
92				// The directory may contain unrelated platform secret files.
93			}
94		}
95	
96		if err := s.validateDeploymentAuthenticationState(ctx, config); err != nil {
97			return err
98		}
99		if err := s.warnShadowedStoredIdentityProviders(ctx, config); err != nil {
100			return err
101		}
102	
103		s.setDeploymentConfiguration(config)
104		slog.Info("loaded deployment configuration", "identityProviders", len(config.identityProviders), "instanceSettings", len(config.instanceSettings))
105		return nil
106	}
107	
108	func newDeploymentConfiguration() *deploymentConfiguration {
109		return &deploymentConfiguration{
110			identityProviders: map[string]*storepb.IdentityProvider{},
111			instanceSettings:  map[storepb.InstanceSettingKey]*storepb.InstanceSetting{},
112		}
113	}
114	
115	func isIdentityProviderDeploymentFilename(name string) bool {
116		// The original database-writing bootstrap accepted every filename with this
117		// prefix and suffix. Continue loading those names so an upgrade cannot
118		// silently fall back to stale credentials stored in the database.
119		return strings.HasPrefix(name, "memos-idp-") && strings.HasSuffix(name, ".json")
120	}
121	
122	func readDeploymentProtoJSON(path string, message proto.Message) error {
123		info, err := os.Stat(path)
124		if err != nil {
125			return errors.Wrap(err, "failed to inspect file")
126		}
127		if !info.Mode().IsRegular() {
128			return errors.New("file must resolve to a regular file")
129		}
130		file, err := os.Open(path)
131		if err != nil {
132			return errors.Wrap(err, "failed to open file")
133		}
134		defer file.Close()
135		info, err = file.Stat()
136		if err != nil {
137			return errors.Wrap(err, "failed to inspect file")
138		}
139		if !info.Mode().IsRegular() {
140			return errors.New("file must resolve to a regular file")
141		}
142		content, err := io.ReadAll(io.LimitReader(file, maxDeploymentConfigurationSize+1))
143		if err != nil {
144			return errors.Wrap(err, "failed to read file")
145		}
146		if len(content) > maxDeploymentConfigurationSize {
147			return errors.Errorf("file exceeds %d bytes", maxDeploymentConfigurationSize)
148		}
149		if err := (protojson.UnmarshalOptions{DiscardUnknown: false}).Unmarshal(content, message); err != nil {
150			if matches := protoJSONUnknownFieldMatcher.FindStringSubmatch(err.Error()); len(matches) == 2 {
151				return errors.Errorf("failed to decode protobuf JSON: unknown field %q", matches[1])
152			}
153			return errors.New("failed to decode protobuf JSON; verify field names, value types, and JSON syntax")
154		}
155		return nil
156	}
157	
158	func validateDeploymentIdentityProvider(provider *storepb.IdentityProvider) error {
159		if provider.Id != 0 {
160			return errors.New("id must be omitted")
161		}
162		if !base.UIDMatcher.MatchString(provider.Uid) {
163			return errors.New("uid is invalid")
164		}
165		if strings.TrimSpace(provider.Name) == "" {
166			return errors.New("name is required")
167		}
168		if provider.Type != storepb.IdentityProvider_OAUTH2 {
169			return errors.New("type must be OAUTH2")
170		}
171		if provider.IdentifierFilter != "" {
172			if _, err := regexp.Compile(provider.IdentifierFilter); err != nil {
173				return errors.Wrap(err, "identifierFilter must be a valid regular expression")
174			}
175		}
176		config := provider.Config.GetOauth2Config()
177		if config == nil {
178			return errors.New("config.oauth2Config is required")
179		}
180		required := []struct {
181			name  string
182			value string
183		}{
184			{name: "clientId", value: config.ClientId},
185			{name: "clientSecret", value: config.ClientSecret},
186			{name: "authUrl", value: config.AuthUrl},
187			{name: "tokenUrl", value: config.TokenUrl},
188			{name: "userInfoUrl", value: config.UserInfoUrl},
189		}
190		for _, field := range required {
191			if strings.TrimSpace(field.value) == "" {
192				return errors.Errorf("config.oauth2Config.%s is required", field.name)
193			}
194		}
195		for _, field := range []struct {
196			name  string
197			value string
198		}{
199			{name: "authUrl", value: config.AuthUrl},
200			{name: "tokenUrl", value: config.TokenUrl},
201			{name: "userInfoUrl", value: config.UserInfoUrl},
202		} {
203			parsed, err := url.ParseRequestURI(field.value)
204			if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
205				return errors.Errorf("config.oauth2Config.%s must be an absolute HTTP(S) URL", field.name)
206			}
207		}
208		if len(config.Scopes) == 0 {
209			return errors.New("config.oauth2Config.scopes is required")
210		}
211		for i, scope := range config.Scopes {
212			if strings.TrimSpace(scope) == "" {
213				return errors.Errorf("config.oauth2Config.scopes[%d] must not be empty", i)
214			}
215		}
216		if config.FieldMapping == nil || strings.TrimSpace(config.FieldMapping.Identifier) == "" {
217			return errors.New("config.oauth2Config.fieldMapping.identifier is required")
218		}
219		return nil
220	}
221	
222	func validateAndNormalizeDeploymentInstanceSetting(setting *storepb.InstanceSetting) error {
223		switch setting.Key {
224		case storepb.InstanceSettingKey_GENERAL:
225			if setting.GetGeneralSetting() == nil {
226				return errors.New("generalSetting must be populated for key GENERAL")
227			}
228			if offset := setting.GetGeneralSetting().WeekStartDayOffset; offset < -1 || offset > 6 {
229				return errors.New("generalSetting.weekStartDayOffset must be between -1 and 6")
230			}
231		case storepb.InstanceSettingKey_STORAGE:
232			storage := setting.GetStorageSetting()
233			if storage == nil {
234				return errors.New("storageSetting must be populated for key STORAGE")
235			}
236			if storage.UploadSizeLimitMb < 0 {
237				return errors.New("storageSetting.uploadSizeLimitMb must not be negative")
238			}
239			if storage.StorageType == storepb.InstanceStorageSetting_S3 {
240				if storage.S3Config == nil {
241					return errors.New("storageSetting.s3Config is required for S3")
242				}
243				for _, field := range []struct {
244					name  string
245					value string
246				}{
247					{name: "accessKeyId", value: storage.S3Config.AccessKeyId},
248					{name: "accessKeySecret", value: storage.S3Config.AccessKeySecret},
249					{name: "endpoint", value: storage.S3Config.Endpoint},
250					{name: "region", value: storage.S3Config.Region},
251					{name: "bucket", value: storage.S3Config.Bucket},
252				} {
253					if strings.TrimSpace(field.value) == "" {
254						return errors.Errorf("storageSetting.s3Config.%s is required", field.name)
255					}
256				}
257			}
258		case storepb.InstanceSettingKey_MEMO_RELATED:
259			if setting.GetMemoRelatedSetting() == nil {
260				return errors.New("memoRelatedSetting must be populated for key MEMO_RELATED")
261			}
262		case storepb.InstanceSettingKey_NOTIFICATION:
263			notification := setting.GetNotificationSetting()
264			if notification == nil {
265				return errors.New("notificationSetting must be populated for key NOTIFICATION")
266			}
267			if email := notification.Email; email != nil && email.Enabled {
268				if strings.TrimSpace(email.SmtpHost) == "" || email.SmtpPort <= 0 || strings.TrimSpace(email.FromEmail) == "" {
269					return errors.New("enabled notification email requires smtpHost, a positive smtpPort, and fromEmail")
270				}
271				if email.UseTls && email.UseSsl {
272					return errors.New("notification email cannot enable both useTls and useSsl")
273				}
274			}
275		case storepb.InstanceSettingKey_AI:
276			if setting.GetAiSetting() == nil {
277				return errors.New("aiSetting must be populated for key AI")
278			}
279			if err := normalizeDeploymentAISetting(setting.GetAiSetting()); err != nil {
280				return err
281			}
282		case storepb.InstanceSettingKey_BASIC, storepb.InstanceSettingKey_TAGS:
283			return errors.Errorf("key %s cannot be deployment configured", setting.Key)
284		default:
285			return errors.Errorf("unsupported instance setting key %s", setting.Key)
286		}
287		return nil
288	}
289	
290	func normalizeDeploymentAISetting(setting *storepb.InstanceAISetting) error {
291		providers := map[string]struct{}{}
292		for i, provider := range setting.Providers {
293			if provider == nil {
294				return errors.Errorf("aiSetting.providers[%d] must not be null", i)
295			}
296			provider.Id = strings.TrimSpace(provider.Id)
297			provider.Title = strings.TrimSpace(provider.Title)
298			provider.Endpoint = strings.TrimSpace(provider.Endpoint)
299			if provider.Id == "" || provider.Title == "" || provider.ApiKey == "" {
300				return errors.Errorf("aiSetting.providers[%d] requires id, title, and apiKey", i)
301			}
302			if _, ok := providers[provider.Id]; ok {
303				return errors.Errorf("aiSetting provider ID %q is duplicated", provider.Id)
304			}
305			providers[provider.Id] = struct{}{}
306			switch provider.Type {
307			case storepb.AIProviderType_OPENAI:
308				if provider.Endpoint == "" {
309					provider.Endpoint = "https://api.openai.com/v1"
310				}
311			case storepb.AIProviderType_GEMINI:
312				if provider.Endpoint == "" {
313					provider.Endpoint = "https://generativelanguage.googleapis.com/v1beta"
314				}
315			default:
316				return errors.Errorf("aiSetting provider %q has unsupported type", provider.Id)
317			}
318		}
319		if transcription := setting.Transcription; transcription != nil {
320			transcription.ProviderId = strings.TrimSpace(transcription.ProviderId)
321			transcription.Model = strings.TrimSpace(transcription.Model)
322			transcription.Language = strings.TrimSpace(transcription.Language)
323			transcription.Prompt = strings.TrimSpace(transcription.Prompt)
324			if transcription.ProviderId != "" {
325				if _, ok := providers[transcription.ProviderId]; !ok {
326					return errors.Errorf("aiSetting transcription providerId %q does not reference a provider", transcription.ProviderId)
327				}
328			}
329			if len(transcription.Model) > maxTranscriptionModelLength || len(transcription.Language) > maxTranscriptionLanguageLength || len(transcription.Prompt) > maxTranscriptionPromptLength {
330				return errors.New("aiSetting transcription configuration exceeds a supported length limit")
331			}
332		}
333		return nil
334	}
335	
336	func (s *Store) validateDeploymentAuthenticationState(ctx context.Context, config *deploymentConfiguration) error {
337		_, generalConfigured := config.instanceSettings[storepb.InstanceSettingKey_GENERAL]
338		if !generalConfigured && len(config.identityProviders) == 0 {
339			general, err := s.getRawInstanceSetting(ctx, storepb.InstanceSettingKey_GENERAL.String())
340			if err != nil {
341				return errors.Wrap(err, "failed to inspect stored GENERAL setting")
342			}
343			if general == nil || !general.GetGeneralSetting().DisallowPasswordAuth {
344				return nil
345			}
346			providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
347			if err != nil {
348				return errors.Wrap(err, "failed to inspect stored identity providers")
349			}
350			if len(providers) == 0 {
351				slog.Warn("stored configuration disables password authentication for regular users but has no identity provider; unrelated deployment files remain loadable because administrator password sign-in is available")
352			}
353			return nil
354		}
355		general, err := s.getRawInstanceSetting(ctx, storepb.InstanceSettingKey_GENERAL.String())
356		if err != nil {
357			return errors.Wrap(err, "failed to read stored GENERAL setting")
358		}
359		if configured := config.instanceSettings[storepb.InstanceSettingKey_GENERAL]; configured != nil {
360			general = cloneInstanceSetting(configured)
361		}
362		if general == nil || !general.GetGeneralSetting().DisallowPasswordAuth {
363			return nil
364		}
365		providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
366		if err != nil {
367			return errors.Wrap(err, "failed to read stored identity providers")
368		}
369		effectiveUIDs := map[string]struct{}{}
370		for _, provider := range providers {
371			effectiveUIDs[provider.Uid] = struct{}{}
372		}
373		for uid := range config.identityProviders {
374			effectiveUIDs[uid] = struct{}{}
375		}
376		if len(effectiveUIDs) == 0 {
377			return errors.New("deployment configuration disables password authentication for regular users but has no effective identity provider")
378		}
379		return nil
380	}
381	
382	func (s *Store) warnShadowedStoredIdentityProviders(ctx context.Context, config *deploymentConfiguration) error {
383		if len(config.identityProviders) == 0 {
384			return nil
385		}
386		providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
387		if err != nil {
388			return errors.Wrap(err, "failed to inspect stored identity providers")
389		}
390		for _, provider := range providers {
391			if _, ok := config.identityProviders[provider.Uid]; ok {
392				slog.Warn("deployment identity provider shadows a stored provider; the stored configuration remains in the database", "uid", provider.Uid)
393			}
394		}
395		return nil
396	}
397	
398	func (s *Store) setDeploymentConfiguration(config *deploymentConfiguration) {
399		copy := newDeploymentConfiguration()
400		for uid, provider := range config.identityProviders {
401			copy.identityProviders[uid] = cloneIdentityProvider(provider)
402		}
403		for key, setting := range config.instanceSettings {
404			copy.instanceSettings[key] = cloneInstanceSetting(setting)
405		}
406		s.deploymentConfigMu.Lock()
407		s.deploymentConfig = copy
408		s.deploymentConfigMu.Unlock()
409	}
410	
411	// IsIdentityProviderDeploymentConfigured reports whether uid is file-backed.
412	func (s *Store) IsIdentityProviderDeploymentConfigured(uid string) bool {
413		s.deploymentConfigMu.RLock()
414		defer s.deploymentConfigMu.RUnlock()
415		_, ok := s.deploymentConfig.identityProviders[uid]
416		return ok
417	}
418	
