14	func (s *APIV1Service) ListLinkedIdentities(ctx context.Context, request *v1pb.ListLinkedIdentitiesRequest) (*v1pb.ListLinkedIdentitiesResponse, error) {
15		user, err := s.resolveUserFromName(ctx, request.Parent)
16		if err != nil {
17			return nil, status.Errorf(codes.InvalidArgument, "invalid parent: %v", err)
18		}
19		userID := user.ID
20	
21		if _, err := s.authorizeUserResourceAccess(ctx, userID, true); err != nil {
22			return nil, err
23		}
24	
25		identities, err := s.Store.ListUserIdentities(ctx, &store.FindUserIdentity{UserID: &userID})
26		if err != nil {
27			return nil, status.Errorf(codes.Internal, "failed to list linked identities: %v", err)
28		}
29	
30		response := &v1pb.ListLinkedIdentitiesResponse{
31			LinkedIdentities: []*v1pb.LinkedIdentity{},
32		}
33		for _, identity := range identities {
34			response.LinkedIdentities = append(response.LinkedIdentities, convertLinkedIdentityFromStore(user, identity))
35		}
36		return response, nil
37	}
