39	func (s *APIV1Service) CreateLinkedIdentity(ctx context.Context, request *v1pb.CreateLinkedIdentityRequest) (*v1pb.LinkedIdentity, error) {
40		user, err := s.resolveUserFromName(ctx, request.Parent)
41		if err != nil {
42			return nil, status.Errorf(codes.InvalidArgument, "invalid parent: %v", err)
43		}
44	
45		currentUser, err := s.fetchCurrentUser(ctx)
46		if err != nil {
47			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
48		}
49		if currentUser == nil {
50			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
51		}
52		if currentUser.ID != user.ID {
53			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
54		}
55	
56		identityProvider, userInfo, err := s.resolveSSOIdentity(ctx, request.IdpName, request.Code, request.RedirectUri, request.CodeVerifier)
57		if err != nil {
58			return nil, err
59		}
60		provider := identityProvider.Uid
61		externUID := userInfo.Identifier
62	
63		if _, err := s.bindSSOIdentityToUser(ctx, currentUser, provider, externUID); err != nil {
64			return nil, err
65		}
66	
67		identity, err := s.Store.GetUserIdentity(ctx, &store.FindUserIdentity{
68			UserID:   &currentUser.ID,
69			Provider: &provider,
70		})
71		if err != nil {
72			return nil, status.Errorf(codes.Internal, "failed to get linked identity: %v", err)
73		}
74		if identity == nil {
75			return nil, status.Errorf(codes.Internal, "linked identity not found after creation")
76		}
77	
78		return convertLinkedIdentityFromStore(user, identity), nil
79	}
