28	// GetNameParentTokens returns the tokens from a resource name.
29	func GetNameParentTokens(name string, tokenPrefixes ...string) ([]string, error) {
30		parts := strings.Split(name, "/")
31		if len(parts) != 2*len(tokenPrefixes) {
32			return nil, errors.Errorf("invalid request %q", name)
33		}
34	
35		var tokens []string
36		for i, tokenPrefix := range tokenPrefixes {
37			if fmt.Sprintf("%s/", parts[2*i]) != tokenPrefix {
38				return nil, errors.Errorf("invalid prefix %q in request %q", tokenPrefix, name)
39			}
40			if parts[2*i+1] == "" {
41				return nil, errors.Errorf("invalid request %q with empty prefix %q", name, tokenPrefix)
42			}
43			tokens = append(tokens, parts[2*i+1])
44		}
45		return tokens, nil
46	}
