48	func ExtractInstanceSettingKeyFromName(name string) (string, error) {
49		const prefix = "instance/settings/"
50		if !strings.HasPrefix(name, prefix) {
51			return "", errors.Errorf("invalid instance setting name: expected prefix %q, got %q", prefix, name)
52		}
53	
54		settingKey := strings.TrimPrefix(name, prefix)
55		if settingKey == "" {
56			return "", errors.Errorf("invalid instance setting name: empty setting key in %q", name)
57		}
58	
59		// Ensure there are no additional path segments
60		if strings.Contains(settingKey, "/") {
61			return "", errors.Errorf("invalid instance setting name: setting key cannot contain '/' in %q", name)
62		}
63	
64		return settingKey, nil
65	}
